import { Fragment } from "react";
import { Eye, ShieldCheck, Sparkles, TrendingUp } from "lucide-react";

const items = [
  {
    icon: Eye,
    title: "HIGHER ENGAGEMENT",
    description: "Keep customers on your page longer",
  },
  {
    icon: ShieldCheck,
    title: "BUILDS CONFIDENCE",
    description: "Let them see the real quality",
  },
  {
    icon: TrendingUp,
    title: "INCREASES CONVERSIONS",
    description: "Fewer doubts, more purchases",
  },
  {
    icon: Sparkles,
    title: "PREMIUM BRAND EXPERIENCE",
    description: "Modern. Interactive. Unforgettable.",
  },
];

export default function Description() {
  return (
    <div className="flex w-full shrink-0 justify-center border-b border-gray-300">
      <ul className="grid w-full max-w-5xl grid-cols-2 items-center gap-4 px-5 py-4 md:flex md:items-center md:justify-between">
        {items.map((item, index) => {
          const Icon = item.icon;

          return (
            <Fragment key={item.title}>
              <li className="flex min-w-0 items-center gap-3 md:w-auto md:shrink-0">
                <Icon
                  aria-hidden="true"
                  className="h-5 w-5 shrink-0 text-[#d4af37]"
                />
                <div className="min-w-0 md:min-w-fit">
                  <p className="text-xs font-semibold tracking-wider text-black md:whitespace-nowrap">
                    {item.title}
                  </p>
                  <p className="text-xs leading-snug text-gray-500 md:whitespace-nowrap">
                    {item.description}
                  </p>
                </div>
              </li>
              {index < items.length - 1 && (
                <li
                  aria-hidden="true"
                  className="hidden h-8 w-px shrink-0 bg-gray-300 md:block"
                />
              )}
            </Fragment>
          );
        })}
      </ul>
    </div>
  );
}
